@dataclass
class WindVector:
    """Represents a wind vector with speed and direction"""
    speed: float  # m/s
    direction: float  # degrees (0 = North, 90 = East)

    def to_components(self) -> Tuple[float, float]:
        """Convert to u,v components (east, north)"""
        rad = math.radians(self.direction)
        u = self.speed * math.sin(rad)  # eastward component
        v = self.speed * math.cos(rad)  # northward component
        return u, v

    @classmethod
    def from_components(cls, u: float, v: float) -> 'WindVector':
        """Create from u,v components"""
        speed = math.sqrt(u**2 + v**2)
        direction = math.degrees(math.atan2(u, v))
        if direction < 0:
            direction += 360
        return cls(speed, direction)

